import { memo } from 'react';
import { createRoot } from 'react-dom/client';
import { ComboBox, Label, Input, Popover, ListBox, ListBoxItem } from 'react-aria-components';

type Source = 'incoming' | 'outgoing';
type StudyRecord = { id: number; label: string };
type Mark = (kind: 'row') => void;

const Row = memo(function Row({ id, label, selected, mark }: StudyRecord & {
  selected: boolean;
  mark: Mark;
}) {
  mark('row');
  return (
    <div data-row={id} aria-selected={selected}>
      <span>{label}</span>
      <input aria-label={`Edit record ${id}`} defaultValue={label} />
    </div>
  );
});

const fruits = ['Apricot', 'Blueberry', 'Cherry'];

function FruitPicker({ onCommit }: { onCommit: (value: string) => void }) {
  return (
    <ComboBox onSelectionChange={key => {
      if (typeof key === 'string' && fruits.includes(key)) onCommit(key);
    }}>
      <Label>Fruit</Label>
      <Input />
      <Popover>
        <ListBox>
          {fruits.map(fruit => <ListBoxItem key={fruit} id={fruit}>{fruit}</ListBoxItem>)}
        </ListBox>
      </Popover>
    </ComboBox>
  );
}

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: Mark,
) {
  const app = createRoot(root);
  const counts: Record<Source, number> = { incoming: 4, outgoing: 7 };
  let source: Source = 'incoming';
  let selectedId = 1;
  let records: StudyRecord[] = [
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' },
  ];
  let nextSession = 0;
  let pickerSession: number | null = null;
  let disposed = false;

  function render() {
    if (disposed) return;
    const badge = `${counts[source]} crates`;
    const session = pickerSession;
    app.render(
      <>
        <div>
          <output data-badge="" title={badge}>{badge}</output>
          <input data-note="" aria-label="Note" />
        </div>
        <div>
          {records.map(({ id, label }) => (
            <Row key={id} id={id} label={label} selected={id === selectedId} mark={mark} />
          ))}
        </div>
        {session !== null && (
          <FruitPicker key={session} onCommit={value => {
            if (pickerSession === session) onCommit(value);
          }} />
        )}
      </>,
    );
  }

  render();

  return {
    count(which: Source, value: number) {
      counts[which] = value;
      if (which === source) render();
    },
    mode(which: Source) {
      source = which;
      render();
    },
    select(id: number) {
      selectedId = id;
      render();
    },
    refetch(nextRecords: StudyRecord[]) {
      records = nextRecords.slice();
      render();
    },
    swap() {
      if (records.length < 2) return;
      const [first, second, ...rest] = records;
      records = [second!, first!, ...rest];
      render();
    },
    open() {
      if (disposed || pickerSession !== null) return;
      pickerSession = ++nextSession;
      render();
    },
    close() {
      if (pickerSession === null) return;
      pickerSession = null;
      render();
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      pickerSession = null;
      app.unmount();
    },
  };
}
